import { pageLoader } from '@/common/helpers';

export const checkoutPage = {
	checkout: null,

	async init(container) {
		const $checkout = container.querySelector('.js-checkout-vue');
		if ($checkout) {
			try {
				const [{ createApp }, { default: Checkout }] = await Promise.all([
					import('vue'),
					import('@/components/features/checkout/checkout.vue'),
				]);

				this.checkout = createApp(Checkout)
					.mixin({
						mounted() {
							if (this.$options.name === Checkout.name || !this.$parent) {
								pageLoader.hide();
							}
						},
					})
					.mount($checkout);
			} catch (error) {
				console.error(error);
				pageLoader.hide();
			}
		} else {
			pageLoader.hide();
		}
	},

	destroy() {
		if (this.checkout) {
			this.checkout.unmount();
			this.checkout = null;
		}
	},
};
